import{_ as a,o as _,a as e,b as o}from"./app.UgfkfLuP.js";const u=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API<a npu_parse_enabled=\\"true\\"></a>","link":"/api/SIMD-API/SIMD-API"},{"text":"C API","link":"/api/SIMD-API/c_api/README"},{"text":"矩阵计算搬运","link":"/api/SIMD-API/c_api/cube_datamove/cube_datamove"},{"text":"矩阵搬出关键特性说明","link":"/api/SIMD-API/c_api/cube_datamove/cube_store_key_features/cube_store_key_features"},{"text":"随路量化","link":"/api/SIMD-API/c_api/cube_datamove/cube_store_key_features/accompanying_quantization"}]},"headers":[],"relativePath":"api/SIMD-API/c_api/cube_datamove/cube_store_key_features/accompanying_quantization.md","filePath":"api/SIMD-API/c_api/cube_datamove/cube_store_key_features/accompanying_quantization.md","outlineHeaders":[{"level":2,"title":"特性说明","slug":"特性说明","link":"#特性说明"}],"lastUpdated":1791622466000}'),c={name:"api/SIMD-API/c_api/cube_datamove/cube_store_key_features/accompanying_quantization.md"};function d(r,t,l,n,i,s){return _(),e("div",null,[...t[0]||(t[0]=[o(`<div><article class="markdown-body"><h1>随路量化</h1><h2 id="特性说明">特性说明<a class="header-anchor" href="#特性说明">​</a></h2><p>矩阵搬出支持随路类型转换和带系数的量化，可在L0C Buffer结果搬出的过程中完成数值处理。量化模式决定处理方式，量化参数提供该模式所需的缩放系数、偏移量等信息；配置量化参数后，仍需在搬出接口中选择对应模式。</p><div data-filter="950"><p>针对Ascend 950PR&amp;950DT系列产品：</p><p>通过<a href="../cube_compute_store/asc_copy_l0c2gm_arch_3510.html">asc_copy_l0c2gm</a>、<a href="../cube_compute_store/asc_copy_l0c2l1_arch_3510.html">asc_copy_l0c2l1</a>或<a href="../cube_compute_store/asc_copy_l0c2ub.html">asc_copy_l0c2ub</a>搬出时，使用<code>quant_pre_mode</code>选择量化模式，其取值见<a href="../../defs/enum/asc_quant_mode.html">asc_quant_mode</a>。根据是否需要量化系数及系数的共享范围，可分为以下三种情况：</p><ul><li><strong>类型转换</strong>：使用<code>asc_quant_mode::F322F16</code>或<code>asc_quant_mode::F322BF16</code>将float转换为half或bfloat16_t，无需配置量化系数，舍入模式采用CAST_RINT。</li><li><strong>Scalar量化</strong>：整个C矩阵共享一个量化参数，参数由QUANT_PRE寄存器提供。</li><li><strong>Tensor/Vector量化</strong>：C矩阵的每一列对应一个8B量化参数，参数shape为[N]，N为C矩阵的列数。参数由Fixpipe Buffer的量化参数区提供，每个元素均为打包后的<code>uint64_t</code>，不能直接使用float数组。</li></ul><p>其中，<code>QF322F16_PRE</code>/<code>VQF322F16_PRE</code>和<code>QF322BF16_PRE</code>/<code>VQF322BF16_PRE</code>虽然也输出half或bfloat16_t，但属于带系数量化，需按Scalar或Vector模式准备参数。模式名称中的<code>V</code>前缀表示Vector粒度。Scalar和Vector使用相同的量化参数编码，各字段含义见<a href="#quant-pre-3510">Ascend 950PR&amp;950DT系列产品编码表</a>。</p><p><strong>配置与调用顺序：</strong></p><ol><li>根据源/目的数据类型、搬出通路和输出布局，在对应搬出接口中确认支持的量化模式及其组合约束。</li><li>按所选模式准备参数：类型转换无需配置系数；Scalar量化通过<a href="../cube_store_aux_config/asc_set_l0c_copy_prequant.html">asc_set_l0c_copy_prequant(scale, offset, is_signed)</a>设置参数；Vector量化将每列参数准备在L1 Buffer，经<a href="../cube_compute_load/asc_copy_l12fb_arch_3510.html">asc_copy_l12fb</a>搬入Fixpipe Buffer的量化参数区，再通过<a href="../cube_store_aux_config/asc_set_l0c_copy_config.html">asc_set_l0c_copy_config</a>设置<code>quant_pre_addr</code>。若Vector参数原先位于GM，需先通过<a href="../cube_compute_load/asc_copy_gm2l1.html">asc_copy_gm2l1</a>搬入L1 Buffer。</li><li>根据输入数据及参数搬运的依赖关系完成<a href="../../sync/intra_core_sync/intra_core_sync.html">核内同步</a>后，调用L0C搬出接口，并在<code>quant_pre_mode</code>中传入所选的<code>asc_quant_mode</code>枚举值。</li></ol><p>Vector量化的<code>quant_pre_addr</code>为量化参数区起始字节地址除以128，不能直接传入元素下标。若还需随路激活，参见<a href="accompanying_relu.html">随路ReLU</a>：激活参数地址索引以64B为单位，与量化参数区独立寻址。两类参数的起始地址及占用范围均不能超出各自区域，具体要求见<a href="../cube_store_aux_config/asc_set_l0c_copy_config.html">asc_set_l0c_copy_config</a>。</p></div><div data-filter="A3,910b"><p>针对以下产品型号：</p><div data-filter="A3"><ul><li>Atlas A3系列产品</li></ul></div><div data-filter="910b"><ul><li>Atlas A2系列产品</li></ul></div><p>通过<a href="../cube_compute_store/asc_copy_l0c2gm_arch_2201.html">asc_copy_l0c2gm</a>或<a href="../cube_compute_store/asc_copy_l0c2l1_arch_2201.html">asc_copy_l0c2l1</a>搬出时，使用整数参数<code>quant_pre</code>选择量化模式，可显式转换<a href="../../defs/enum/asc_quant_mode.html">asc_quant_mode</a>枚举得到模式编码。Scalar量化通过<a href="../cube_store_aux_config/asc_set_l0c_copy_prequant.html">asc_set_l0c_copy_prequant</a>的<code>uint64_t config</code>重载传入打包后的参数，其中低32位为float的位模式，不能通过浮点数到整数的数值转换得到；Vector量化为每列准备一个打包后的<code>uint64_t</code>参数，经<a href="../cube_compute_load/asc_copy_l12fb_arch_2201.html">asc_copy_l12fb</a>搬入Fixpipe Buffer，再通过<a href="../cube_store_aux_config/asc_set_l0c_copy_config.html">asc_set_l0c_copy_config</a>配置量化参数起始地址索引。参数编码见<a href="#quant-pre-2201">量化参数编码表</a>，调用时需遵循对应接口的搬运、对齐及同步约束。</p></div><p>当前支持的量化模式及其功能描述如下：</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>DEQF16,                // DeQuant_Float16：int32_t反量化成half，scalar量化
VDEQF16,               // Vector_DeQuant_Float16：int32_t反量化成half，tensor量化
QF322B8_PRE,           // Quant_Float32_2_B8：float量化成int8_t/uint8_t，scalar量化
VQF322B8_PRE,          // Vector_Quant_Float32_2_B8：float量化成int8_t/uint8_t，tensor量化
REQ8,                  // ReQuant_int8：int32_t重量化成int8_t/uint8_t，scalar量化
VREQ8,                 // Vector_ReQuant_int8：int32_t重量化成int8_t/uint8_t，tensor量化
</code></pre></div><div data-filter="950"><p>除上述量化模式外，Ascend 950PR&amp;950DT系列产品还额外支持以下量化模式：</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>QF322FP8_PRE,          // Quant_Float32_2_FP8: float量化成fp8_e4m3fn_t，scalar量化
VQF322FP8_PRE,         // Vector_Quant_Float32_2_FP8: float量化成fp8_e4m3fn_t，tensor量化
QF322HIF8_PRE,         // Quant_Float32_2_HIF8: float量化成hifloat8_t(Half to Away Round)，scalar量化
VQF322HIF8_PRE,        // Vector_Quant_Float32_2_HIF8: float量化成hifloat8_t(Half to Away Round)，tensor量化
QF322HIF8_PRE_HYBRID,  // Quant_Float32_2_HIF8_Hybrid: float量化成hifloat8_t(Hybrid Round)，scalar量化
VQF322HIF8_PRE_HYBRID, // Vector_Quant_Float32_2_HIF8_Hybrid: float量化成hifloat8_t(Hybrid Round)，tensor量化
QS322BF16_PRE,         // Quant_Int32_2_BFloat16: int32_t量化成bfloat16_t，scalar量化
VQS322BF16_PRE,        // Vector_Quant_Int32_2_BFloat16: int32_t量化成bfloat16_t，tensor量化
QF322F16_PRE,          // Quant_Float32_2_Float16: float量化成half，scalar量化
VQF322F16_PRE,         // Vector_Quant_Float32_2_Float16: float量化成half，tensor量化
QF322BF16_PRE,         // Quant_Float32_2_BFloat16: float量化成bfloat16_t，scalar量化
VQF322BF16_PRE,        // Vector_Quant_Float32_2_BFloat16: float量化成bfloat16_t，tensor量化
QF322F32_PRE,          // Quant_Float32_2_Float32: float量化成float，scalar量化，使用有限精度的量化系数，需按输入范围验证误差
VQF322F32_PRE,         // Vector_Quant_Float32_2_Float32: float量化成float，tensor量化，使用有限精度的量化系数，需按输入范围验证误差
</code></pre></div></div><p>不同量化模式的量化算法详细介绍参见<a href="accompanying_quantization_and_relu_scenario_combination.html">随路量化与随路ReLU场景组合</a>。</p><p>量化参数比特位含义见下表：</p><div data-filter="A3,910b"><p><a id="quant-pre-2201"></a></p><p><strong>表1</strong> 量化参数QUANT_PRE比特位含义映射表（<a href="../../../../../guide/programming_guide/language_extension/simd_builtin_keywords.html">NPU架构版本2201</a>）</p><table><thead><tr><th>模式</th><th>比特位数</th><th>变量名</th><th>作用介绍</th></tr></thead><tbody><tr><td>•(V)REQ8<br>•(V)QF322B8_PRE<br>•(V)DEQF16</td><td>0~31</td><td>M1</td><td>32位数视为float，硬件以(1, 8, 10)的格式，即1个符号位、8个指数位和10个尾数位作为量化计算所需要乘的值。其中31位为符号位，23~30位为指数位，13~22位为尾数位。</td></tr><tr><td>•(V)REQ8<br>•(V)QF322B8_PRE<br>•(V)DEQF16</td><td>32~35</td><td>N</td><td>4位比特位，表示范围为[1, 16]（b&#39;0000对应表示1，b&#39;1111对应表示16）。<br>当模式为(V)REQ8时，MCB标志位置为1时，将输入的值进行右移N比特位。当模式为(V)QF322B8_PRE，N为无效变量。</td></tr><tr><td>•(V)REQ8<br>•(V)QF322B8_PRE<br>•(V)DEQF16</td><td>36</td><td>MCB标志位</td><td>Mode Control Bit。如果置为0，输入的int32_t会被直接转换为float，N为无效值。如果置为1，输入的int32_t会先右移N比特位，转变成int16_t，然后转换为float。当模式为(V)QF322B8_PRE时，此标志位为无效比特。</td></tr><tr><td>•(V)REQ8<br>•(V)QF322B8_PRE<br>•(V)DEQF16</td><td>37~45</td><td>Offset</td><td>9bit的整型数据，源数据乘以量化系数或者随路系数的计算结果，可以与Offset表示的整数值进行相加。若不使用offset，请置为0。<br>当模式为(V)DEQF16时，此变量为无效变量。</td></tr><tr><td>•(V)REQ8<br>•(V)QF322B8_PRE<br>•(V)DEQF16</td><td>46</td><td>Sign标志位</td><td>如果置为1，表明量化结果是signed(int8)；如果置为0，表明量化结果是unsigned(uint8)。仅在(V)REQ8、(V)QF322B8_PRE中会用到。</td></tr><tr><td>•(V)REQ8<br>•(V)QF322B8_PRE<br>•(V)DEQF16</td><td>47~63</td><td>-</td><td>无效比特位，用户无需关注。</td></tr></tbody></table></div><div data-filter="950"><p><a id="quant-pre-3510"></a></p><p><strong>表2</strong> 量化参数QUANT_PRE比特位含义映射表（<a href="../../../../../guide/programming_guide/language_extension/simd_builtin_keywords.html">NPU架构版本3510</a>）</p><table><thead><tr><th>模式</th><th>比特位数</th><th>变量名</th><th>作用介绍</th></tr></thead><tbody><tr><td>•(V)REQ8<br>•(V)QF322B8_PRE<br>•(V)DEQF16<br>•(V)QF322FP8_PRE<br>•(V)QF322HIF8_PRE<br>•(V)QF322HIF8_PRE_HYBRID<br>•(V)QS322BF16_PRE<br>•(V)QF322F16_PRE<br>•(V)QF322BF16_PRE<br>•(V)QF322F32_PRE<br>•(V)REQ4<br>•(V)QF322S4_PRE</td><td>0~12</td><td>-</td><td>无效比特位，用户无需关注。</td></tr><tr><td>同第一行</td><td>13~31</td><td>M1</td><td>数据类型视为float，硬件以(1, 8, 10)的格式，即1个符号位、8个指数位和10个尾数位作为量化计算所需要乘的值。其中31位为符号位，23~30位为指数位，13~22位为尾数位。其值不能为inf/nan。</td></tr><tr><td>同第一行</td><td>32~36</td><td>-</td><td>无效比特位，用户无需关注。</td></tr><tr><td>同第一行</td><td>37~45</td><td>Offset</td><td>9bit整形数据，源数据乘以量化系数或者随路系数的计算结果，可以与Offset表示的整数值进行相加。若不使用offset，请置为0。当模式为(V)REQ8、(V)QF322B8_PRE、(V)REQ4、(V)QF322S4_PRE时该变量生效。</td></tr><tr><td>同第一行</td><td>46</td><td>Sign标志位</td><td>如果置为1，表明量化结果是signed(int8)；如果为置为0，表明量化结果是unsigned(uint8)。仅在(V)REQ8、(V)QF322B8_PRE中会用到。</td></tr><tr><td>同第一行</td><td>47~63</td><td>-</td><td>无效比特位，用户无需关注。</td></tr></tbody></table></div><p><strong>使用约束与参数精度：</strong></p><ul><li><p>量化参数不能为inf、nan或非规格化数；配置前需检查缩放系数，具体限制见对应配置接口。</p></li><li><p>缩放系数按表中有效位参与计算，不保留完整FP32尾数精度。输出仍为float的量化模式也会受到该有效精度的影响。</p></li><li><p>Offset、Sign只在表中列出的模式下生效。</p><div data-filter="A3,910b"><p>Atlas A3系列产品和Atlas A2系列产品的N/MCB只在表中列出的模式下生效。</p></div><div data-filter="950"><p>Ascend 950PR&amp;950DT系列产品中32~36位无效，不能沿用Atlas A3系列产品和Atlas A2系列产品的右移配置。</p></div></li><li><p>Vector量化的参数按原始C矩阵的N维列索引对应。分块搬出时，应同步检查参数区偏移、列数、对齐及占用范围。Fixpipe Buffer的量化区和激活区独立寻址，不能把元素下标直接传给地址索引参数。</p></li><li><p>不同搬出任务需要不同系数时，应在对应搬出执行前重新配置。<code>asc_set_l0c_copy_config</code>每次同时覆盖激活地址、量化地址和UnitFlag初始化参数，三者的含义见该接口的参数说明。</p></li></ul><p><strong>使用示例：</strong></p><p><a href="https://gitcode.com/cann/asc-devkit/blob/master/examples/02_simd_c_api/03_c_api/03_matrix_compute/asc_copy_l0c2gm/README.md">asc_copy_l0c2gm样例</a>的场景4、5分别展示Scalar和Vector量化。运行时按样例声明的产品支持范围选择环境。算法示意及量化与ReLU的配合见<a href="accompanying_quantization_and_relu_scenario_combination.html">随路量化与随路ReLU场景组合</a>。</p></article></div>`,1)])])}const f=a(c,[["render",d]]);export{u as __pageData,f as default};
